from fractions import Fraction


def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    prefix = [0] * (n + 1)
    for i, value in enumerate(a):
        prefix[i + 1] = prefix[i] + value

    # For each right endpoint r, maximize (prefix[r] - prefix[l]) / (r - l)
    # over l <= r-k. Maintain the lower convex hull of eligible prefix points.
    hull = []
    head = 0
    best_num, best_den = 0, 1

    def cross(o, p, q):
        return (p[0] - o[0]) * (q[1] - o[1]) - (p[1] - o[1]) * (q[0] - o[0])

    for r in range(k, n + 1):
        point = (r - k, prefix[r - k])
        while len(hull) >= head + 2 and cross(hull[-2], hull[-1], point) <= 0:
            hull.pop()
        hull.append(point)

        while head + 1 < len(hull):
            x1, y1 = hull[head]
            x2, y2 = hull[head + 1]
            if (prefix[r] - y2) * (r - x1) >= (prefix[r] - y1) * (r - x2):
                head += 1
            else:
                break

        x, y = hull[head]
        num, den = prefix[r] - y, r - x
        if num * best_den > best_num * den:
            best_num, best_den = num, den

    divisor = __import__("math").gcd(best_num, best_den)
    return [best_num // divisor, best_den // divisor]
